app.use('/api',async(req,res,next)=>{
 if(req.path==='/health'||req.path==='/auth/login'||req.path==='/auth/register'||req.method==='OPTIONS')return next();
 try{
  const user=await getUserFromToken(requestToken(req));
  if(!user||user.status!=='active')return res.status(401).json({error:'Authentication required'});
  (req as any).user=user;(req.headers as any)['x-practice-session']=user.id;
  if(!req.body||typeof req.body!=='object')req.body={};
  req.body.sessionId=user.id;(req.query as any).sessionId=user.id;
  if(user.role!=='admin'){
   const dbPath=req.path.match(/^\/databases\/([0-9a-f-]{36})(?:\/|$)/i);
   const databaseId=String(req.query.databaseId||req.body.databaseId||dbPath?.[1]||'');
   if(databaseId&&!await workspaceOwnedByUser(databaseId,user.id))return res.status(404).json({error:'Database not found'});
   const questionPath=req.path.match(/^\/questions\/([0-9a-f-]{36})(?:\/|$)/i);
   if(questionPath&&!await questionBelongsToUser(questionPath[1],user.id))return res.status(404).json({error:'Question not found'});
   const setPath=req.path.match(/^\/question-sets\/([0-9a-f-]{36})(?:\/|$)/i);
   if(setPath&&!await questionSetBelongsToUser(setPath[1],user.id))return res.status(404).json({error:'Question set not found'});
   const collectionPath=req.path.match(/^\/collections\/([0-9a-f-]{36})(?:\/|$)/i);
   if(collectionPath&&!await collectionBelongsToUser(collectionPath[1],user.id))return res.status(404).json({error:'Collection not found'});
   if(req.path==='/interview/score'){
	const ids=[...new Set((Array.isArray(req.body.answers)?req.body.answers:[]).map((answer:any)=>String(answer.questionId||'')))];
   for(const id of ids)if(!await questionBelongsToUser(String(id),user.id))return res.status(404).json({error:'Question not found'});
   }
  }
  next();
 }catch(error){res.status(503).json({error:'Authentication service unavailable'})}
});
