app.post('/api/auth/register',async(req,res)=>{try{const name=String(req.body.name||'').trim(),email=String(req.body.email||'').trim().toLowerCase(),password=String(req.body.password||'');if(name.length<2||!z.string().email().safeParse(email).success||password.length<8)return res.status(400).json({error:'Name, valid email and password of at least 8 characters are required'});if(await getUserByEmail(email))return res.status(409).json({error:'Email already registered'});const id=crypto.randomUUID();await createUser({id,name,email,password_hash:hashPassword(password),role:'student',status:'active',created_at:new Date(),last_login_at:null});await ensureUserWorkspace(id);await migrateUserWorkspaceQuestions(id);const session=await createSession(id);setSessionCookie(res,session.token);await audit(id,'user.register','user',id,{},req.ip);res.status(201).json({user:{id,name,email,role:'student'},expiresAt:session.expiresAt})}catch(e){res.status((e as any).code===11000?409:400).json({error:(e as Error).message})}});
async function dbRow(id:string){const workspace=await getWorkspaceById(id);if(!workspace)throw new Error('Database not found');return workspace}
async function ownedDbRow(id:string,user:any){const d=await dbRow(id);if(user.role!=='admin'&&d.owner_user_id!==user.id)throw Object.assign(new Error('Database not found'),{status:404});return d}
app.post('/api/databases/import-file',upload.single('file'),async(req,res)=>{
 try{
  const workspace=await ownedDbRow(String(req.body.databaseId),(req as any).user);
  if(!req.file)throw new Error('File required');
  const sql=req.file.buffer.toString('utf8'),id=crypto.randomUUID();
  await executeImport(workspace.schema_name,sql);
  const tables=await listTables(workspace.schema_name);
  await createSchemaImport({id,database_id:workspace.id,source_type:'sql',filename:req.file.originalname,raw_text:sql,extracted_sql:sql,review_json:{tables},status:'approved',created_at:new Date()});
  res.json({ok:true,tables,importId:id});
 }catch(error){res.status((error as any).status||400).json({error:(error as Error).message})}
});
app.post('/api/databases/import-image',upload.single('file'),async(req,res)=>{
 if(!openai)return res.status(503).json({error:'OPENAI_API_KEY is not configured'});
 let createdDatabase:any=null,draftCreated=false;
 try{
  if(!req.file)throw new Error('Image required');
  const mime=req.file.mimetype;
  if(!['image/png','image/jpeg','image/webp'].includes(mime))throw new Error('Use PNG, JPEG, or WEBP');
  const data=`data:${mime};base64,${req.file.buffer.toString('base64')}`;
  const plan=await extractSchemaFromImage(data);
  if(!plan.tables.length||!plan.sql.trim())throw new Error(plan.warnings.join('; ')||'No tables could be identified in this image');
  if(!plan.sampleDataSql.trim()||plan.sampleDataSource==='none')throw new Error('AI could not create sample rows. Add sample data manually or upload a clearer schema image.');
  await validateImageSampleData(plan);
  const user=(req as any).user;
  const workspace=req.body.createDatabase==='true'
   ?(createdDatabase=await createImageDatabase(plan.databaseName||req.file.originalname.replace(/\.[^.]+$/,''),user.id))
   :await ownedDbRow(String(req.body.databaseId||''),user);
  const importId=crypto.randomUUID();
  await createSchemaImport({id:importId,database_id:workspace.id,source_type:'image',filename:req.file.originalname,extracted_sql:plan.sql,review_json:plan,status:'draft',created_at:new Date()});
  draftCreated=true;
  res.json({ok:true,importId,plan,database:{id:workspace.id,name:workspace.name,slug:workspace.slug,schema_name:workspace.schema_name,dialect:workspace.dialect,description:workspace.description},tables:await listTables(workspace.schema_name),requiresReview:true});
 }catch(error){
  if(createdDatabase&&!draftCreated){
   try{await pool.query(`DROP SCHEMA IF EXISTS ${quoteIdent(createdDatabase.schema_name)} CASCADE`);await pool.query('DELETE FROM app_databases WHERE id=$1',[createdDatabase.id]);await deleteWorkspaceRecord(createdDatabase.id)}catch{}
  }
  res.status((error as any).status||400).json({error:(error as Error).message});
 }
});
app.post('/api/databases/:id/import-review/:importId/approve',async(req,res)=>{
 try{
  const workspace=await dbRow(req.params.id),record=await getSchemaImport(req.params.importId,String(workspace.id));
  if(!record)throw new Error('Import review not found');
  const plan=record.review_json||{},ddl=String(plan.sql||record.extracted_sql||''),includeSampleData=req.body.includeSampleData!==false;
  const sampleData=includeSampleData?String(plan.sampleDataSql||''):'';
  await executeImport(workspace.schema_name,[ddl,sampleData].filter(Boolean).join('\n'));
  await approveSchemaImport(req.params.importId);
  res.json({ok:true,sampleDataIncluded:Boolean(sampleData),sampleDataSource:plan.sampleDataSource||'none',tables:await listTables(workspace.schema_name),schema:await schemaSnapshot(workspace.schema_name)});
 }catch(error){res.status(400).json({error:(error as Error).message})}
});
async function createImageDatabase(rawName:string,userId:string){const name=rawName.trim().slice(0,80)||'Imported Schema';const base=name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,40)||'imported-schema';const suffix=crypto.randomUUID().slice(0,8);const id=crypto.randomUUID();const slug=`${base}-${suffix}`;const schemaName=`practice_${base.replace(/-/g,'_').slice(0,42)}_${suffix}`;await createPracticeSchema(schemaName);try{const workspace={id,name,slug,schema_name:schemaName,dialect:'postgresql',description:'Created from an AI-reviewed schema image',owner_user_id:userId,created_at:new Date()};await pool.query('INSERT INTO app_databases(id,name,slug,schema_name,description,owner_user_id) VALUES($1,$2,$3,$4,$5,$6)',[id,name,slug,schemaName,workspace.description,userId]);await createWorkspace(workspace);return workspace}catch(error){await pool.query(`DROP SCHEMA IF EXISTS ${quoteIdent(schemaName)} CASCADE`);await pool.query('DELETE FROM app_databases WHERE id=$1',[id]);throw error}}
async function ensureImageSampleData(plan:any){const validationSchema=`image_validation_${crypto.randomUUID().replaceAll('-','')}`;await createPracticeSchema(validationSchema);let repaired=false;try{await executeImport(validationSchema,plan.sql);const tables=await listTables(validationSchema);if(!tables.length)throw new Error('The extracted schema created no tables');let insertSql=plan.sampleDataSql;for(let attempt=0;attempt<3;attempt++){try{await executeImport(validationSchema,insertSql);plan.sampleDataSql=insertSql;break}catch(error){const code=(error as any).code;if(!['23505','23503'].includes(code)||attempt===2)throw new Error(`AI sample data violates a unique or foreign-key constraint: ${(error as Error).message}`);const fullReplacement=await generateAdditionalSampleRows(plan.sql,'',tables.map(table=>({table:table.name,missingRows:20})));if(!fullReplacement.sql.trim())throw new Error('AI could not regenerate valid sample rows');insertSql=fullReplacement.sql;repaired=true}}const getMissing=async()=>{const counts=await Promise.all(tables.map(async table=>({table:table.name,count:Number((await pool.query(`SELECT count(*)::int AS count FROM ${quoteIdent(validationSchema)}.${quoteIdent(table.name)}`)).rows[0].count)})));return counts.filter(entry=>entry.count<20).map(entry=>({table:entry.table,missingRows:20-entry.count}))};for(let attempt=0;attempt<2;attempt++){const missing=await getMissing();if(!missing.length){if(repaired)plan.warnings.push('AI regenerated or added rows to meet the minimum of 20 rows per table.');return}const additional=await generateAdditionalSampleRows(plan.sql,plan.sampleDataSql,missing);if(!additional.sql.trim())throw new Error('AI returned no additional sample rows');try{await executeImport(validationSchema,additional.sql)}catch(error){const code=(error as any).code;if(!['23505','23503'].includes(code))throw error;const replacement=await generateAdditionalSampleRows(plan.sql,'',tables.map(table=>({table:table.name,missingRows:20})));await pool.query(`DROP SCHEMA IF EXISTS ${quoteIdent(validationSchema)} CASCADE`);await createPracticeSchema(validationSchema);await executeImport(validationSchema,plan.sql);await executeImport(validationSchema,replacement.sql);plan.sampleDataSql=replacement.sql;repaired=true;continue}plan.sampleDataSql+=`\n${additional.sql}`;repaired=true}const missing=await getMissing();if(missing.length)throw new Error(`Could not reach 20 rows in every table: ${missing.map(entry=>`${entry.table} has ${20-entry.missingRows}`).join(', ')}`)}finally{await pool.query(`DROP SCHEMA IF EXISTS ${quoteIdent(validationSchema)} CASCADE`)}}
async function validateImageSampleData(plan:any){const validationSchema=`image_validation_${crypto.randomUUID().replaceAll('-','')}`;await createPracticeSchema(validationSchema);try{await executeImport(validationSchema,plan.sql);try{await executeImport(validationSchema,plan.sampleDataSql)}catch(error){const code=(error as any).code;if(code==='23505')throw new Error('AI sample data contains duplicate primary/unique keys. Re-upload the image to generate a fresh 5–10 row sample.');if(code==='23503')throw new Error('AI sample data contains invalid foreign-key references. Re-upload the image to generate a fresh sample.');throw error}const tables=await listTables(validationSchema);if(!tables.length)throw new Error('The extracted schema created no tables');const counts=await Promise.all(tables.map(async table=>({table:table.name,count:Number((await pool.query(`SELECT count(*)::int AS count FROM ${quoteIdent(validationSchema)}.${quoteIdent(table.name)}`)).rows[0].count)})));const invalid=counts.filter(entry=>entry.count<5||entry.count>10);if(invalid.length)throw new Error(`Each table must have 5–10 sample rows. Current counts: ${counts.map(entry=>`${entry.table}: ${entry.count}`).join(', ')}`);return counts}finally{await pool.query(`DROP SCHEMA IF EXISTS ${quoteIdent(validationSchema)} CASCADE`)}}
