app.delete('/api/databases/:id/tables/:tableName',async(req,res)=>{try{const d=await dbRow(req.params.id),name=req.params.tableName;if(!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(name))return res.status(400).json({error:'Invalid table name'});const exists=await pool.query("SELECT 1 FROM information_schema.tables WHERE table_schema=$1 AND table_name=$2 AND table_type='BASE TABLE'",[d.schema_name,name]);if(!exists.rowCount)return res.status(404).json({error:'Table not found'});await pool.query(`DROP TABLE ${quoteIdent(d.schema_name)}.${quoteIdent(name)}`);res.json({ok:true,deletedTable:name,tables:await listTables(d.schema_name)})}catch(e){const code=(e as any).code;res.status(code==='2BP01'?409:400).json({error:code==='2BP01'?'Cannot delete this table while other tables reference it. Remove those foreign-key relationships first.':(e as Error).message})}});
