function sameResult(a:any,b:any){const norm=(x:any)=>{const cols=(x.columns||[]).map((c:string)=>c.toLowerCase());const rows=(x.rows||[]).map((r:any)=>cols.map((c:string)=>r[c]===undefined?null:r[c]));return JSON.stringify({columns:cols,rows})};return norm(a)===norm(b)}
