const askAiLimits=new Map<string,{count:number;windowStarted:number}>();
function limitAskAi(req:any,res:any,next:any){const key=String(req.user?.id||req.ip||'unknown'),now=Date.now();let bucket=askAiLimits.get(key);if(!bucket||now-bucket.windowStarted>=60000){if(askAiLimits.size>=10000)askAiLimits.delete(askAiLimits.keys().next().value!);bucket={count:1,windowStarted:now};askAiLimits.set(key,bucket);return next()}if(bucket.count>=12)return res.status(429).json({error:'AI request limit reached. Try again in a minute.'});bucket.count++;next()}
const askAiAttachment=z.object({name:z.string().min(1).max(160),mimeType:z.enum(['image/png','image/jpeg','image/webp','image/gif']),dataUrl:z.string().max(7_100_000)}).strict();
const askAiRequest=z.object({conversationId:z.string().uuid().optional(),content:z.string().trim().max(4000).default(''),attachments:z.array(askAiAttachment).max(4).default([])}).strict().superRefine((value,context)=>{
 if(!value.content&&!value.attachments.length)context.addIssue({code:z.ZodIssueCode.custom,message:'Add a message or attach an image'});
 let totalBytes=0;
 for(const [index,attachment] of value.attachments.entries()){
  const match=attachment.dataUrl.match(/^data:(image\/(?:png|jpeg|webp|gif));base64,([A-Za-z0-9+/]*={0,2})$/);
  if(!match||match[1]!==attachment.mimeType){context.addIssue({code:z.ZodIssueCode.custom,path:['attachments',index,'dataUrl'],message:'Invalid image attachment'});continue}
  const bytes=Buffer.from(match[2],'base64');
  const isPng=attachment.mimeType==='image/png'&&bytes.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10]));
  const isJpeg=attachment.mimeType==='image/jpeg'&&bytes[0]===255&&bytes[1]===216&&bytes[2]===255;
  const isGif=attachment.mimeType==='image/gif'&&['GIF87a','GIF89a'].includes(bytes.subarray(0,6).toString());
  const isWebp=attachment.mimeType==='image/webp'&&bytes.subarray(0,4).toString()==='RIFF'&&bytes.subarray(8,12).toString()==='WEBP';
  if(!isPng&&!isJpeg&&!isGif&&!isWebp)context.addIssue({code:z.ZodIssueCode.custom,path:['attachments',index],message:'Attachment content does not match a supported image type'});
  if(!bytes.length||bytes.length>5*1024*1024)context.addIssue({code:z.ZodIssueCode.custom,path:['attachments',index],message:'Each image must be 5 MB or smaller'});
  totalBytes+=bytes.length;
 }
 if(totalBytes>5*1024*1024)context.addIssue({code:z.ZodIssueCode.custom,path:['attachments'],message:'Images must total 5 MB or less'});
});
