app.post('/api/interview/learning/:sessionId/answer',async(req,res)=>{const parsed=z.object({questionId:z.string().min(1).max(100),answer:z.string().trim().min(1).max(8000)}).safeParse(req.body);if(!parsed.success)return res.status(400).json({error:'Answer must contain 1 to 8000 non-whitespace characters'});try{const result=await answerLearningInterview({sessionId:req.params.sessionId,userId:String((req as any).user.id),...parsed.data});if(result.status==='not_found')return res.status(404).json({error:'Interview not found'});if(result.status==='question_not_in_session')return res.status(403).json({error:'Question is not part of this interview'});if(result.status==='expired')return res.status(410).json({error:'Interview time limit expired'});if(result.status==='closed')return res.status(409).json({error:'Interview is already closed'});if(result.status==='already_answered')return res.status(409).json({error:'This question already has a saved response'});if(result.status==='feedback_unavailable')return res.json({saved:true,feedbackAvailable:false,response:result.response});res.json({saved:true,feedbackAvailable:true,response:result.response})}catch{res.status(503).json({error:'Interview answer could not be saved'})}});
