app.post('/api/interview/score',async(req,res)=>{const sessionId=String(req.body.sessionId||''),userId=String((req as any).user.id),session=await getInterviewSession(sessionId,userId),answers=Array.isArray(req.body.answers)?req.body.answers:[];if(!session)return res.status(404).json({error:'Interview not found'});if(session.status!=='in_progress')return res.status(409).json({error:'Interview is already complete'});if(new Date(session.deadline_at)<new Date())return res.status(410).json({error:'Interview time limit has expired'});const allowed=new Set(session.question_ids.map(String));if(answers.some((answer:any)=>!allowed.has(String(answer.questionId))))return res.status(400).json({error:'Answer contains a question outside this interview'});let correct=0;const details:any[]=[];for(const answer of answers){const question=await getQuestion(String(answer.questionId));if(!question)continue;const workspace=await dbRow(String(question.database_id));try{const actual=await executeReadOnly(workspace.schema_name,String(answer.sql||''));const isCorrect=sameResult(actual,question.expected_json);if(isCorrect)correct++;details.push({questionId:question.id,correct:isCorrect,executionMs:actual.executionMs})}catch(error){details.push({questionId:question.id,correct:false,error:(error as Error).message})}}const result={score:answers.length?Math.round(correct/answers.length*100):0,correct,total:answers.length,details,responses:answers.map((answer:any)=>({question_id:String(answer.questionId),sql:String(answer.sql||'')}))};if(!await completeInterview(sessionId,userId,result))return res.status(409).json({error:'Interview is already complete'});res.json({sessionId,...result})});
